+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const DATA_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'data');
+
+const TOOLS = [
+  {
+    name: 'file_metadata',
+    description:
+      'Return metadata for a file under the workspace data directory: its relative path, byte size, and lowercase extension. File contents are never exposed.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        path: {
+          type: 'string',
+          description: 'Relative path of the file within the data directory.',
+        },
+      },
+      required: ['path'],
+      additionalProperties: false,
+    },
+  },
+];
+
+export async function listTools() {
+  return TOOLS;
+}
+
+export async function callTool(name, args) {
+  if (name !== 'file_metadata') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  const input = args || {};
+  // Strict schema validation: only `path` is allowed and required.
+  for (const key of Object.keys(input)) {
+    if (key !== 'path') {
+      throw new Error(`Invalid arguments: unknown property '${key}'`);
+    }
+  }
+  if (typeof input.path !== 'string' || input.path.length === 0) {
+    throw new Error('Invalid arguments: path is required and must be a non-empty string');
+  }
+
+  const rel = input.path;
+  if (path.isAbsolute(rel)) {
+    throw new Error('Invalid path: absolute paths are not allowed');
+  }
+
+  // Resolve and ensure the target stays inside the data directory.
+  const dataRoot = path.resolve(DATA_DIR);
+  const full = path.resolve(dataRoot, rel);
+  if (full !== dataRoot && !full.startsWith(dataRoot + path.sep)) {
+    throw new Error('Invalid path: traversal outside the data directory is not allowed');
+  }
+
+  let stat;
+  try {
+    stat = await fs.stat(full);
+  } catch (_err) {
+    throw new Error(`File not found: ${rel}`);
+  }
+  if (!stat.isFile()) {
+    throw new Error(`Not a file: ${rel}`);
+  }
+
+  const normalized = path.relative(dataRoot, full);
+  const ext = path.extname(normalized).toLowerCase();
+  const text =
+    `path: ${normalized}\n` +
+    `size: ${stat.size} bytes\n` +
+    `extension: ${ext}`;
+
+  return {
+    content: [{ type: 'text', text }],
+  };
+}
